import React, { Fragment, useState, useContext } from "react";
import "./AddProduct.css";
import CartContext from "../../store/cart-context";

const AddProduct = () => {
  const cartCtx = useContext(CartContext);

  const [tshirtName, setTshirtName] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [large, setLarge] = useState(0);
  const [medium, setMedium] = useState(0);
  const [small, setSmall] = useState(0);
  const [submitted, setSubmitted] = useState(false);

  const tshirtNameHandler = (event) => {
    setTshirtName(event.target.value);
  };
  const descHandler = (event) => {
    setDescription(event.target.value);
  };
  const priceHandler = (event) => {
    setPrice(event.target.value);
  };
  const largehandler = (event) => {
    setLarge(event.target.value);
  };
  const mediumHandler = (event) => {
    setMedium(event.target.value);
  };
  const smallHandler = (event) => {
    setSmall(event.target.value);
  };

  const addProductHandler = (event) => {
    event.preventDefault();
    setSubmitted(true);
  };

  const addToCartHandler = () => {
    cartCtx.addItem({
      id: Math.random().toString(),
      name: tshirtName,
      description: description,
      price: price,
      amount: 1,
    });
  };

  return (
    <Fragment>
      <form onSubmit={addProductHandler}>
        <div className="container">
          <div>
            <label htmlFor="name">T-Shirt Name</label> <br></br>
            <input
              type="text"
              name="name"
              id="candyname"
              value={tshirtName}
              onChange={tshirtNameHandler}
            ></input>
          </div>

          <div>
            <label htmlFor="desc">Description</label>
            <br></br>
            <input
              type="text"
              name="desc"
              id="desc"
              value={description}
              onChange={descHandler}
            ></input>
          </div>
          <div>
            <label htmlFor="price">Price</label>
            <br></br>
            <input
              type="number"
              name="price"
              id="price"
              value={price}
              onChange={priceHandler}
            ></input>
          </div>
          <div className="quantity">
            <label htmlFor="quantity">Quantity Avilable</label>
            <br></br>
            <div>
              <label htmlFor="large">L</label>
              <input
                type="number"
                name="large"
                id="large"
                value={large}
                onChange={largehandler}
              ></input>
            </div>
            <div>
              <label htmlFor="medium">M</label>
              <input
                type="number"
                name="medium"
                id="medium"
                value={medium}
                onChange={mediumHandler}
              ></input>
            </div>
            <div>
              <label htmlFor="small">S</label>
              <input
                type="number"
                name="small"
                id="small"
                value={small}
                onChange={smallHandler}
              ></input>
            </div>
          </div>
          <div>
            <button>AddProduct</button>
          </div>
        </div>
      </form>
      {submitted && (
        <div className="details">
          <div>
            <h2>{tshirtName}</h2>
          </div>
          <div>
            <p>{description}</p>
          </div>
          <div>
            <p>Price: {price}</p>{" "}
          </div>
          <div>
            <button
              onClick={() => {
                addToCartHandler;
              }}
            >
              Buy Large{large}
            </button>
            <button
              onClick={() => {
                /* Logic for buying medium */
              }}
            >
              Buy Medium {medium}
            </button>
            <button
              onClick={() => {
                /* Logic for buying small */
              }}
            >
              Buy Small{small}
            </button>
          </div>
        </div>
      )}
    </Fragment>
  );
};
export default AddProduct;
